import chalk from "chalk";

const rainbow = (text) => {
  const colors = [
    chalk.redBright,
    chalk.yellowBright,
    chalk.greenBright,
    chalk.cyanBright,
    chalk.blueBright,
    chalk.magentaBright
  ];
  return text
    .split("")
    .map((char, i) => colors[i % colors.length](char))
    .join("");
};

